BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='30s';
SELECT json_build_object('section','books','books',json_agg(row_to_json(q) ORDER BY q."sourceItemId")) FROM (
SELECT s.id AS "sourceItemId",s.novel_id AS "novelId",n.title,n.status AS "novelStatus",s.status AS "sourceStatus",s.deleted_at AS "sourceDeletedAt",n.deleted_at AS "novelDeletedAt",s.channel_app_id AS "channelAppId",n.slug,n.locale,
(SELECT count(*) FROM novel_chapter c WHERE c.novel_id=n.id AND c.deleted_at IS NULL AND c.status='preview') AS "previewChapterCount",
(SELECT count(*) FROM novel_chapter c JOIN novel_chapter_content cc ON cc.novel_chapter_id=c.id WHERE c.novel_id=n.id AND c.deleted_at IS NULL AND c.status='preview' AND btrim(cc.body)<>'') AS "readablePreviewChapterCount",
(SELECT count(*) FROM novel_chapter c WHERE c.novel_id=n.id AND c.status='withdrawn') AS "withdrawnChapterCount",
li.id AS "lastItemId",li.task_id AS "lastTaskId",li.status AS "lastItemStatus",li.error->>'code' AS "lastErrorCode",jsonb_strip_nulls(jsonb_build_object('kind',li.error#>'{detail,kind}','stage',li.error#>'{detail,stage}','receivedType',li.error#>'{detail,receivedType}','chapterIndex',li.error#>'{detail,chapterIndex}')) AS "lastErrorDetail",li.created_at AS "lastItemCreatedAt"
FROM novel_source_item s LEFT JOIN novel n ON n.id=s.novel_id LEFT JOIN LATERAL (SELECT i.id,i.task_id,i.status,i.error,i.created_at FROM channel_sync_task_item i JOIN channel_sync_task t ON t.id=i.task_id WHERE i.novel_source_item_id=s.id AND t.task_type='moboreader.preview_refresh.v1' ORDER BY i.created_at DESC,i.id DESC LIMIT 1) li ON TRUE
WHERE s.id=ANY(ARRAY['02b6dff3-d973-4922-ad43-d4ab61a895b5','031216f8-1a1b-463b-856a-74b4712c889b','0325c057-214b-46d1-a1f5-5f481e03d7b1','056374b0-ec90-4b5d-9543-aef5b081aeaf','0dd6a38a-e438-4654-b608-3bc60743c304','0faed754-957d-461f-abe6-00c1b1e9e32b','1044615d-8566-4134-910e-b5220166b0a9','11e79e01-415e-4c38-9429-3b2bb3157cd6','14006896-96c5-4acd-b833-9d830e2f3101','175c6473-dbbd-41a7-9b5a-e720f1ada72c','182ae182-d5c2-4ab3-a45e-c312051fd04c','185d2e13-e620-483d-8fde-21441afb372e','1df34abe-29f9-4b4f-a897-ebb5101ae8fc','1f0df82e-498b-44cb-b66e-06c57d6d1890','1f9c9b7b-d58a-4557-8f1a-ed2c441569cb','217e972c-1b14-43f9-86e9-c40606e9f7bb','234abdc6-224c-4dab-b73b-565bebf51302','24c306c7-1fd0-4700-baa4-3a484cd46837','2cb5ec08-7a37-4ec3-8258-52cd10ea1d73','3236281e-8892-422f-8f46-f23e916ae834','35980fa4-b3f3-4057-adcd-28cb74b02523','366461bb-fbe3-418a-ab65-04b184cf0140','38c5670b-242e-403d-b921-0c2bbe1b2e66','3b2987f7-1ff4-48ba-9b55-8363a5783d53','3cda0227-f309-40ea-989a-0411a8fa5460','3d427bac-d7cc-440a-829c-cc5c319ccc74','3d5c16dd-44ed-44b7-af61-26dfe50d794a','3e858f0f-c235-4224-9783-d4dddbdf77a9','48652907-0196-4ec7-a3ad-c9ad3e1df6fa','4b87f14c-e188-4205-b612-a7cdfd634e7f','4cc30b02-93c4-4fac-a5d1-754a79222a35','4d46f103-1780-4000-9ecd-86b6dafb9ccf','537aab35-9d84-4f4f-a02a-d48c2a1234a7','6681979c-cfed-459d-8669-1f1d5f5d20e8']::uuid[])) q;
COMMIT;
